function countUnivalSubtrees(root) {
  let count = 0;

  function isUnival(node) {
    if (!node) {
      return true;
    }
    const left = isUnival(node.left);
    const right = isUnival(node.right);
    if (!left || !right) {
      return false;
    }
    if (node.left && node.left.val !== node.val) {
      return false;
    }
    if (node.right && node.right.val !== node.val) {
      return false;
    }
    count++;
    return true;
  }

  isUnival(root);
  return count;
}

